export function getEventBySlug(slug: string): NewsEventItem | undefined {
  return allNewsEvents.find((e) => e.slug === slug);
}

export function getRelatedEvents(currentSlug: string, count = 3): NewsEventItem[] {
  const current = getEventBySlug(currentSlug);
  if (!current) return allNewsEvents.slice(0, count);
  return allNewsEvents
    .filter((e) => e.slug !== currentSlug && e.categorySlug === current.categorySlug)
    .slice(0, count);
}
